const body = $input.first().json.body;
const jobTitle = body.job_title || 'Nao informado';
const jobDesc = body.job_description || 'Nao informado';

return [{
  json: {
    job_title: jobTitle,
    job_description: jobDesc,
    message: `Workflow recebeu: ${jobTitle} - ${jobDesc}`
  }
}];

const data = $input.first().json;

// Simula resultado da API
const score = Math.floor(Math.random() * 40) + 60;
const status = score >= 70 ? 'APROVADO' : 'REJEITADO';

return [{
  json: {
    score: score,
    report: `Analise para: ${data.job_title}`,
    status: status,
    message: `Score: ${score}/100 - ${status}`,
    input: data
  }
}];
